# Function to check if a path is drive relative
def is_drive_relative_path(s):
    return bool(re.match(r'^[A-Za-z]:[^\\/]', s))

# Modify the sanitize_path function
def sanitize_path(s, force=False):
    """Sanitizes and normalizes path on Windows"""
    if sys.platform == 'win32':
        force = False
        drive_or_unc, _ = os.path.splitdrive(s)
    elif force:
        drive_or_unc = ''
    else:
        return s

    # Check if the path is drive relative
    if is_drive_relative_path(s):
        norm_path = s
    else:
        norm_path = os.path.normpath(remove_start(s, drive_or_unc)).split(os.path.sep)
        if drive_or_unc:
            norm_path.pop(0)

    sanitized_path = [
        path_part if path_part in ['.', '..'] else re.sub(r'(?:[/<>:"\|?*]|[\s.]$)', '#', path_part)
        for path_part in norm_path]

    if drive_or_unc:
        sanitized_path.insert(0, drive_or_unc + os.path.sep)
    elif force and s and s[0] == os.path.sep:
        sanitized_path.insert(0, os.path.sep)

    return os.path.normpath(os.path.join(*sanitized_path))
